CREATE TABLE tenants (id BINARY(16) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, timezone VARCHAR(64) NOT NULL);
CREATE TABLE users (id BINARY(16) PRIMARY KEY, tenant_id BINARY(16) NOT NULL, okta_subject VARCHAR(255) NOT NULL UNIQUE, role VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), INDEX ix_user_tenant(tenant_id));
CREATE TABLE services (id BINARY(16) PRIMARY KEY, tenant_id BINARY(16) NOT NULL, name VARCHAR(120) NOT NULL, description VARCHAR(1000), category VARCHAR(80), duration_minutes INT NOT NULL, price DECIMAL(12,2) NOT NULL, status VARCHAR(30) NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), INDEX ix_service_tenant(tenant_id), CONSTRAINT ck_service_duration CHECK(duration_minutes > 0), CONSTRAINT ck_service_price CHECK(price >= 0));
CREATE TABLE staff (id BINARY(16) PRIMARY KEY, tenant_id BINARY(16) NOT NULL, user_id BINARY(16), name VARCHAR(120) NOT NULL, status VARCHAR(30) NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (user_id) REFERENCES users(id), INDEX ix_staff_tenant(tenant_id));
CREATE TABLE staff_services (tenant_id BINARY(16) NOT NULL, staff_id BINARY(16) NOT NULL, service_id BINARY(16) NOT NULL, PRIMARY KEY(tenant_id,staff_id,service_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (staff_id) REFERENCES staff(id), FOREIGN KEY (service_id) REFERENCES services(id));
CREATE TABLE staff_availability (id BINARY(16) PRIMARY KEY, tenant_id BINARY(16) NOT NULL, staff_id BINARY(16) NOT NULL, day_of_week INT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, type VARCHAR(30) NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (staff_id) REFERENCES staff(id), INDEX ix_availability_staff_day(tenant_id,staff_id,day_of_week), CONSTRAINT ck_availability_times CHECK(start_time < end_time));
CREATE TABLE bookings (id BINARY(16) PRIMARY KEY, tenant_id BINARY(16) NOT NULL, service_id BINARY(16) NOT NULL, staff_id BINARY(16) NOT NULL, start_at TIMESTAMP(6) NOT NULL, end_at TIMESTAMP(6) NOT NULL, status VARCHAR(30) NOT NULL, customer_name VARCHAR(120) NOT NULL, pet_name VARCHAR(120) NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (service_id) REFERENCES services(id), FOREIGN KEY (staff_id) REFERENCES staff(id), INDEX ix_booking_overlap(tenant_id,staff_id,status,start_at,end_at), INDEX ix_booking_calendar(tenant_id,start_at));
